import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

const VALID_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];

export function validateThreshold(thresholdStr) {
  const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
  if (!match) {
    return {
      valid: false,
      error: `Invalid threshold format: '${thresholdStr}'. Expected format: <metric>=<number>`
    };
  }

  const [, metricId, valueStr] = match;
  const value = parseFloat(valueStr);

  if (!Number.isFinite(value)) {
    return {
      valid: false,
      error: `Invalid threshold value: '${valueStr}'. Must be a number.`
    };
  }

  if (value < 0 || value > 1) {
    return {
      valid: false,
      error: `Invalid threshold value: '${value}'. Threshold must be between 0 and 1.`
    };
  }

  if (!VALID_METRIC_IDS.includes(metricId)) {
    return {
      valid: false,
      error: `Unknown metric: '${metricId}'. Valid metrics: ${VALID_METRIC_IDS.join(', ')}`
    };
  }

  return {
    valid: true,
    metric: metricId,
    min: value
  };
}

