input.new_string:
export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  // Compute threshold results
  const thresholdResults = [];
  let allThresholdsPassed = true;

  Object.entries(thresholds).forEach(([metricId, minValue]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    if (!metric) {
      return; // Should not happen if validation was done, but skip silently
    }

    const score = metric.score;
    const passed = score !== null && score >= minValue;
    if (!passed) {
      allThresholdsPassed = false;
    }

    thresholdResults.push({
      metric: metricId,
      min: minValue,
      score: score,
      passed
    });
  });

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Only add threshold fields if thresholds were provided
  if (Object.keys(thresholds).length > 0) {
    report.passed = allThresholdsPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

