const __dirname = path.dirname(fileURLToPath(import.meta.url));

console.log('=== ACCEPTANCE CRITERIA TESTS ===\n');

// Load test data
const dataset = loadDataset({
  outputsPath: path.join(__dirname, 'outputs.json'),
  referencesPath: path.join(__dirname, 'refs.json')
});

const evaluations = runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('Test Data Setup:');
console.log('Outputs:', dataset.outputs);
console.log('References:', dataset.references);
