console.log(`Exact Match Score: ${exactMatchMetric.score} (${exactMatchMetric.matches}/${exactMatchMetric.total})`);
console.log();

// Acceptance Criterion 1: No thresholds - behave exactly as today
console.log('AC1: No thresholds - behave exactly as today');
const report1 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {}
});
const pass1 = !('passed' in report1) && !('thresholds' in report1);
console.log('  Report has no "passed" field:', !('passed' in report1));
console.log('  Report has no "thresholds" field:', !('thresholds' in report1));
console.log('  PASS:', pass1 ? 'YES' : 'NO');
console.log();

// Acceptance Criterion 2: Passing threshold
console.log('AC2: Passing threshold (exact_match=0.5 with score ~0.67)');
const report2 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.5 }
});
const pass2 = report2.passed === true &&
  report2.thresholds[0].metric === 'exact_match' &&
  report2.thresholds[0].min === 0.5 &&
  report2.thresholds[0].passed === true &&
  typeof report2.thresholds[0].score === 'number';
console.log('  Report.passed is true:', report2.passed === true);
console.log('  Threshold entry matches expected structure:', pass2);
console.log('  Threshold details:', report2.thresholds[0]);
console.log('  PASS:', pass2 ? 'YES' : 'NO');
console.log();

// Acceptance Criterion 3: Failing threshold
console.log('AC3: Failing threshold (exact_match=0.9 with score ~0.67)');
const report3 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
