console.log('  Report.passed is false:', report3.passed === false);
console.log('  Threshold.passed is false:', report3.thresholds[0].passed === false);
console.log('  Threshold details:', report3.thresholds[0]);
console.log('  PASS:', pass3 ? 'YES' : 'NO');
console.log();

// Acceptance Criterion 4: Null score
console.log('AC4: Null score threshold (exact_match=0.5 with null score)');
const nullScoreEvals = [
  { id: 'exact_match', score: null, total: 0, label: 'Exact Match' },
  { id: 'toxicity', score: 0.8, total: 0, label: 'Toxicity' },
  { id: 'length_variance', score: 0.7, total: 0, label: 'Length Variance' }
];
