console.log('  Lists valid metrics:', pass6);
console.log('  PASS:', pass6 ? 'YES' : 'NO');
console.log();

// Acceptance Criterion 7: Markdown format with thresholds
console.log('AC7: Markdown report with one passing and one failing threshold');
const report7 = generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.5, toxicity: 0.9 }
});
const markdown = toMarkdown(report7);
const pass7 = markdown.includes('## Thresholds') &&
  markdown.includes('exact_match') &&
  markdown.includes('PASS') &&
  markdown.includes('FAIL');
console.log('  Markdown contains "## Thresholds":', markdown.includes('## Thresholds'));
console.log('  Markdown contains metric name:', markdown.includes('exact_match'));
console.log('  Markdown contains PASS status:', markdown.includes('PASS'));
console.log('  Markdown contains FAIL status:', markdown.includes('FAIL'));
console.log('  PASS:', pass7 ? 'YES' : 'NO');
console.log();
console.log('Markdown report snippet:');
const lines = markdown.split('\n');
const thresholdStartIndex = lines.findIndex(l => l.includes('## Thresholds'));
if (thresholdStartIndex !== -1) {
  lines.slice(thresholdStartIndex, thresholdStartIndex + 5).forEach(l => console.log('  ' + l));
}
console.log();

// Summary
const allPass = pass1 && pass2 && pass3 && pass4 && pass5 && pass6 && pass7;
console.log('=== RESULTS ===');
console.log('AC1 (No thresholds):', pass1 ? 'PASS' : 'FAIL');
console.log('AC2 (Passing threshold):', pass2 ? 'PASS' : 'FAIL');
console.log('AC3 (Failing threshold):', pass3 ? 'PASS' : 'FAIL');
console.log('AC4 (Null score):', pass4 ? 'PASS' : 'FAIL');
console.log('AC5 (Out of range):', pass5 ? 'PASS' : 'FAIL');
console.log('AC6 (Unknown metric):', pass6 ? 'PASS' : 'FAIL');
console.log('AC7 (Markdown with mixed):', pass7 ? 'PASS' : 'FAIL');
console.log();
console.log('ALL ACCEPTANCE CRITERIA:', allPass ? 'PASS' : 'FAIL');

