14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	const VALID_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];
17	
18	export function validateThreshold(thresholdStr) {
19	  const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
20	  if (!match) {
21	    return {
22	      valid: false,
23	      error: `Invalid threshold format: '${thresholdStr}'. Expected format: <metric>=<number>`
24	    };
25	  }
26	
27	  const [, metricId, valueStr] = match;
28	  const value = parseFloat(valueStr);
29	
30	  if (!Number.isFinite(value)) {
31	    return {
32	      valid: false,
33	      error: `Invalid threshold value: '${valueStr}'. Must be a number.`
34	    };
35	  }
36	
37	  if (value < 0 || value > 1) {
38	    return {
39	      valid: false,
40	      error: `Invalid threshold value: '${value}'. Threshold must be between 0 and 1.`
41	    };
42	  }
43	
44	  if (!VALID_METRIC_IDS.includes(metricId)) {
45	    return {
46	      valid: false,
47	      error: `Unknown metric: '${metricId}'. Valid metrics: ${VALID_METRIC_IDS.join(', ')}`
48	    };
49	  }
50	
51	  return {
52	    valid: true,
53	    metric: metricId,
54	    min: value
55	  };
56	}
