58	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
59	  if (!outputsPath) {
60	    throw new Error('outputsPath is required for evaluation.');
61	  }
62	
63	  const outputsAbsolute = path.resolve(outputsPath);
64	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
65	  const outputs = JSON.parse(outputsRaw);
66	
67	  let references = [];
68	  let referencesAbsolute = null;
69	  if (referencesPath) {
70	    referencesAbsolute = path.resolve(referencesPath);
71	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
72	    references = JSON.parse(referencesRaw);
73	  }
74	
75	  return {
76	    outputs,
77	    references,
78	    outputsPath: outputsAbsolute,
79	    referencesPath: referencesAbsolute
80	  };
81	}
82	
83	export function runEvaluations({
84	  outputs,
85	  references,
86	  metrics = DEFAULT_METRICS
87	} = {}) {
88	  const outs = ensureArray(outputs);
89	  const refs = ensureArray(references);
90	
91	  const evaluations = metrics.map((metric) => {
92	    if (typeof metric === 'function') {
93	      return metric(outs, refs);
94	    }
95	    if (metric && typeof metric.evaluate === 'function') {
96	      return metric.evaluate(outs, refs);
97	    }
98	    throw new Error('Invalid metric supplied to runEvaluations.');
99	  });
100	
101	  return evaluations;
102	}
103	
104	export function generateReport({
105	  evaluations,
106	  outputsPath,
107	  referencesPath,
108	  generatedAt = new Date().toISOString(),
109	  thresholds = {}
110	}) {
111	  const totalSamples = evaluations.reduce((total, metric) => {
112	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
113	    return total;
114	  }, 0);
115	
116	  // Compute threshold results
117	  const thresholdResults = [];
118	  let allThresholdsPassed = true;
119	
120	  Object.entries(thresholds).forEach(([metricId, minValue]) => {
121	    const metric = evaluations.find((m) => m.id === metricId);
122	    if (!metric) {
123	      return; // Should not happen if validation was done, but skip silently
124	    }
125	
126	    const score = metric.score;
127	    const passed = score !== null && score >= minValue;
128	    if (!passed) {
129	      allThresholdsPassed = false;
130	    }
131	
132	    thresholdResults.push({
133	      metric: metricId,
134	      min: minValue,
135	      score: score,
136	      passed
137	    });
138	  });
139	
140	  const report = {
141	    metadata: {
142	      generatedAt,
143	      outputsPath,
144	      referencesPath,
145	      totalSamples
146	    },
147	    metrics: evaluations
148	  };
149	
150	  // Only add threshold fields if thresholds were provided
151	  if (Object.keys(thresholds).length > 0) {
152	    report.passed = allThresholdsPassed;
153	    report.thresholds = thresholdResults;
154	  }
155	
156	  return report;
157	}
158	
159	export function writeReport({
160	  report,
161	  format = 'json',
162	  reportPath,
163	  fs: fsModule = defaultFs
164	}) {
165	  const resolved = resolveReportPath(reportPath, format);
166	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
167	  fsModule.writeFileSync(resolved, payload, 'utf8');
168	  return resolved;
169	}
