3	export function toJson(report) {
4	  return JSON.stringify(report, null, 2);
5	}
6	
7	export function toMarkdown(report) {
8	  const lines = [];
9	  lines.push('# FRAI Evaluation Report');
10	  lines.push('');
11	  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
12	  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
13	  if (report.metadata.referencesPath) {
14	    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
15	  }
16	  lines.push(`- **Total Samples:** ${report.metadata.totalSamples}`);
17	  lines.push('');
18	  lines.push('## Metrics');
19	  lines.push('');
20	  report.metrics.forEach((metric) => {
21	    lines.push(`### ${metric.label}`);
22	    lines.push('');
23	    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
24	    if (typeof metric.total === 'number') {
25	      lines.push(`- **Total Samples:** ${metric.total}`);
26	    }
27	    if (typeof metric.matches === 'number') {
28	      lines.push(`- **Matches:** ${metric.matches}`);
29	    }
30	    if (typeof metric.flagged === 'number') {
31	      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
32	    }
33	    if (typeof metric.averageDelta === 'number') {
34	      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
35	    }
36	    lines.push('');
37	  });
38	
39	  // Add Thresholds section if thresholds exist
40	  if (report.thresholds && report.thresholds.length > 0) {
41	    lines.push('## Thresholds');
42	    lines.push('');
43	    report.thresholds.forEach((threshold) => {
44	      const status = threshold.passed ? 'PASS' : 'FAIL';
45	      const scoreDisplay = threshold.score !== null ? threshold.score : 'null';
46	      lines.push(`- **${threshold.metric}:** min ${threshold.min}, actual ${scoreDisplay} → ${status}`);
47	    });
48	    lines.push('');
49	  }
50	
51	  lines.push('---');
52	  lines.push('*Generated by FRAI Evaluation Harness*');
53	  return lines.join('\n');
54	}
55	
56	export function resolveReportPath(reportPath, format = 'json') {
57	  if (!reportPath) {
58	    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
59	  }
60	  const ext = path.extname(reportPath);
61	  if (!ext) {
62	    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
63	  }
64	  return reportPath;
65	}
66	
67	export default {
68	  toJson,
69	  toMarkdown,
70	  resolveReportPath
71	};
