477	function runEvalCommand(options: EvalOptions) {
478	  assertFileExists(options.outputs);
479	
480	  // Parse and validate thresholds
481	  const thresholds: Record<string, number> = {};
482	  if (options.threshold && options.threshold.length > 0) {
483	    for (const thresholdStr of options.threshold) {
484	      const result = (Eval.validateThreshold as unknown as (str: string) => any)(thresholdStr);
485	      if (!result.valid) {
486	        log.error(result.error);
487	        process.exit(2);
488	      }
489	      thresholds[result.metric] = result.min;
490	    }
491	  }
492	
493	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
494	    outputsPath: options.outputs,
495	    referencesPath: options.references
496	  });
497	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
498	    outputs: dataset.outputs,
499	    references: dataset.references
500	  });
501	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
502	    evaluations,
503	    outputsPath: dataset.outputsPath,
504	    referencesPath: dataset.referencesPath,
505	    thresholds
506	  });
507	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
508	    report,
509	    format: options.format ?? 'json',
510	    reportPath: options.report
511	  });
512	  log.success('Evaluation report generated.', { path: resolvedPath });
513	
514	  // Exit with code 1 if any threshold failed
515	  if (report.passed === false) {
516	    process.exit(1);
517	  }
518	}
