590	    !options.ci &&
591	    !options.setup &&
592	    !options.listDocs &&
593	    !options.clean &&
594	    !options.update &&
595	    !options.showConfig &&
596	    !options.key;
597	  if (exportOnly) {
598	    exportDocsAsPdf();
599	    return;
600	  }
601	  const showConfigOnly =
602	    options.showConfig &&
603	    !options.scan &&
604	    !options.ci &&
605	    !options.setup &&
606	    !options.listDocs &&
607	    !options.clean &&
608	    !options.update &&
609	    !options.exportPdf &&
610	    !options.key;
611	  if (showConfigOnly) {
612	    showConfigStatus();
613	    return;
614	  }
615	  await runGenerateFlow(options);
616	}
