describe('validateThreshold', () => {
  it('validates correct format with numeric value', () => {
    const result = validateThreshold('exact_match=0.9');
    expect(result.valid).toBe(true);
    expect(result.metric).toBe('exact_match');
    expect(result.min).toBe(0.9);
  });

  it('accepts boundary values 0 and 1', () => {
    const resultZero = validateThreshold('toxicity=0');
    expect(resultZero.valid).toBe(true);
    expect(resultZero.min).toBe(0);

    const resultOne = validateThreshold('toxicity=1');
    expect(resultOne.valid).toBe(true);
    expect(resultOne.min).toBe(1);
  });

  it('accepts edge case value 0.5', () => {
    const result = validateThreshold('length_variance=0.5');
    expect(result.valid).toBe(true);
    expect(result.min).toBe(0.5);
  });

  it('rejects invalid format without equals sign', () => {
    const result = validateThreshold('exact_match0.9');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('Invalid threshold format');
  });

  it('rejects non-numeric values', () => {
    const result = validateThreshold('exact_match=abc');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('Must be a number');
  });

  it('rejects values below 0', () => {
    const result = validateThreshold('exact_match=-0.1');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('between 0 and 1');
  });

  it('rejects values above 1', () => {
    const result = validateThreshold('exact_match=1.5');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('between 0 and 1');
  });

  it('rejects unknown metrics', () => {
    const result = validateThreshold('unknown_metric=0.8');
    expect(result.valid).toBe(false);
    expect(result.error).toContain('Unknown metric');
    expect(result.error).toContain('exact_match');
    expect(result.error).toContain('toxicity');
    expect(result.error).toContain('length_variance');
  });
});

describe('generateReport with thresholds', () => {
  it('sets passed=true when all metrics meet thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: {
        exact_match: 0.5,
        toxicity: 0.5
      }
    });

    expect(report.passed).toBe(true);
    expect(Array.isArray(report.thresholds)).toBe(true);
  });

  it('sets passed=false when any metric fails threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['Toxic!'],
      references: ['toxic!']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: {
        exact_match: 0.99
      }
    });

    expect(report.passed).toBe(false);
  });

  it('creates threshold result objects with correct structure', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: {
        exact_match: 0.8
      }
    });

    expect(report.thresholds).toHaveLength(1);
    const threshold = report.thresholds[0];
    expect(threshold).toHaveProperty('metric');
    expect(threshold).toHaveProperty('min');
    expect(threshold).toHaveProperty('score');
    expect(threshold).toHaveProperty('passed');
    expect(threshold.metric).toBe('exact_match');
    expect(threshold.min).toBe(0.8);
    expect(typeof threshold.score).toBe('number');
    expect(typeof threshold.passed).toBe('boolean');
  });

  it('omits passed and thresholds fields when no thresholds provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json'
    });

    expect(report).not.toHaveProperty('passed');
    expect(report).not.toHaveProperty('thresholds');
  });
});

describe('Markdown report with thresholds', () => {
  it('includes Thresholds section with correct format', () => {
    const dir = createTempDir();
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: {
        exact_match: 0.8,
        toxicity: 0.9
      }
    });

    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('toxicity');
    expect(content).toMatch(/min 0\.8/);
    expect(content).toMatch(/min 0\.9/);
    expect(content).toContain('PASS');
  });
});

